#include "transport.hpp"
#include <iostream>
using namespace m1pn;
namespace {void ck(bool x,const char*s){if(!x)throw std::runtime_error(s);} Field state(const Spatial&f,const Angular&a){Field u=Field::Zero(f.nodes,a.q);for(int i=0;i<f.nodes;++i){Vec v=Vec::Zero(a.q);set_low(v,Four(1+.08*f.coordinates(i,0),.12,.03,0));for(int k=4;k<a.q;++k)v[k]=3.*std::sin((i+1.)*(k+1));u.row(i)=v.transpose();}return u;}}
int main(){try{for(int dimension:{1,2,3}){MeshSpec ms;ms.dimension=dimension;ms.elements=4;Spatial fe(ms);Angular pn(7);Numerics no;no.r2=true;no.gamma=.001;no.stabilization="m1pn_ghost_local_projected_p4";Transport tr(pn,fe,no);Field u=state(fe,pn);Stage full=tr.evaluate(0,u,true),limited=tr.evaluate(0,u,false);ck(maxabs(full.rate-full.target)<2e-9,"unlimited coupled rate recovers PN target");Numerics zero=no;zero.gamma=0;Transport tr0(pn,fe,zero);GhostLocalProjection ghost(fe,no.gamma,pn.speed);ck(maxabs(fe.M*(full.target-tr0.linear_target(u))-ghost.apply(u))<2e-9,"stabilization exactly once in consistent mass target");ck(full.diagnostics.high_rate_error<1e-10,"unlimited higher rates retained");ck(limited.diagnostics.active_pairs>0,"active MCL pair limiter");ck(limited.diagnostics.target_recovery<1e-8,"limited M1 target recovery");ck(limited.diagnostics.high_rate_error<1e-9,"synchronized high rates");ck(limited.diagnostics.mass_residual<1e-7,"consistent PN mass residual");double dt=.1*std::min(fe.cfl_step,1./tr.generator_norm_bound);for(int i=0;i<fe.nodes;++i)ck(exact::cone(project(u.row(i).transpose()+dt*limited.rate.row(i).transpose())),"limited Euler state cone");std::cout<<"P7 ghost coupling nodes="<<fe.nodes<<" active="<<limited.diagnostics.active_pairs<<" mass_residual="<<limited.diagnostics.mass_residual<<"\n";}}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}return 0;}
